using System.IO; using System.Text; class Program { static void Main() { string path = "index.html"; string corruptedText = File.ReadAllText(path, Encoding.UTF8); Encoding win1252 = Encoding.GetEncoding(1252); byte[] originalBytes = win1252.GetBytes(corruptedText); string fixedText = Encoding.UTF8.GetString(originalBytes); File.WriteAllText(path, fixedText, new UTF8Encoding(false)); } }
